using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;
public static class InspectWorldMap {
 public static string Main(){if(Application.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit mode required");var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;var rows=new List<object>();try{foreach(string scene in RacePlaylists.Scenes){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");var renderers=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.enabled&&r.name.StartsWith("Ground_")).ToArray();var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);rows.Add(new{scene,min=bounds.min.ToString(),max=bounds.max.ToString(),roots=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().Select(g=>g.name).ToArray()});}}finally{EditorSceneManager.OpenScene(original);}var s=Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented);Directory.CreateDirectory("Docs/WorldMap");File.WriteAllText("Docs/WorldMap/world-inventory.json",s);return s;}
}
